def decimal_to_Octal(deciNum):
    """Write a python function to convert decimal number to octal number."""
    if deciNum == 0:
        return 0
    sign = -1 if deciNum < 0 else 1
    n = abs(deciNum)
    octal = 0
    place = 1
    while n > 0:
        octal += (n % 8) * place
        n //= 8
        place *= 10
    return sign * octal
